# Generated by rbx. CMS's Polygon importer (cmscontrib/loaders/polygon.py) runs
# this file when it imports the problem; Polygon and Codeforces ignore it.
#
# CMS merges `general` into the task and `datasets[<testset>]` into its dataset,
# which is how it learns what problem.xml cannot tell it. This file runs inside
# the importer, so it can compile programs and store them with CMS's own
# FileCacher, like the importer does for the checker.
import datetime
import os
import shutil
import subprocess
import tempfile
import xml.etree.ElementTree as ET

CONFIG = {}  # rbx:config

_FILES = os.path.dirname(os.path.abspath(__file__))
_ROOT = os.path.dirname(_FILES)
_TASK = os.path.basename(_ROOT)


def _pack_input(data, answer):
    # Must match rbx.box.packaging.cms.communication.pack_input.
    return b'RBX-CMS-INPUT %d %d\n' % (len(data), len(answer)) + data + answer


def _compile(source, output, flags, *extra):
    # `flags` come from the language's `cms` extension in env.rbx.yml.
    subprocess.run(
        ['g++', '-x', 'c++']
        + list(flags)
        + ['-static', '-I', _FILES]
        + list(extra)
        + ['-o', output, os.path.join(_FILES, source)],
        check=True,
    )


def _read(path):
    with open(path, 'rb') as f:
        return f.read()


def _testcases(pack):
    # The importer marks every test public, so the tests are stored again with
    # only the right ones public. An interactive problem's manager never sees the
    # answer, so with `pack` each stored input carries it. The same files the
    # importer reads, codenames as it names them.
    from cms.db import Testcase
    from cms.db.filecacher import FileCacher

    cacher = FileCacher()
    build = tempfile.mkdtemp()
    public = CONFIG['public']
    testset = ET.parse(os.path.join(_ROOT, 'problem.xml')).getroot()
    testset = testset.find('judging').find('testset')
    input_pattern = testset.find('input-path-pattern').text
    answer_pattern = testset.find('answer-path-pattern').text
    testcases = {}
    for i in range(int(testset.find('test-count').text)):
        input_file = os.path.join(_ROOT, input_pattern % (i + 1))
        answer_file = os.path.join(_ROOT, answer_pattern % (i + 1))
        if pack:
            input_file_to_store = os.path.join(build, 'input%d' % i)
            with open(input_file_to_store, 'wb') as f:
                f.write(_pack_input(_read(input_file), _read(answer_file)))
        else:
            input_file_to_store = input_file
        codename = '%03d' % i
        testcases[codename] = Testcase(
            codename,
            public == 'all' or i in public,
            cacher.put_file_from_path(
                input_file_to_store, 'Input %d for task %s' % (i, _TASK)
            ),
            cacher.put_file_from_path(
                answer_file, 'Output %d for task %s' % (i, _TASK)
            ),
        )
    return testcases


def _communication(config):
    from cms.db import Manager
    from cms.db.filecacher import FileCacher

    cacher = FileCacher()
    build = tempfile.mkdtemp()
    defines = []
    if config['checker_runner']:
        checker = os.path.join(build, 'checker')
        _compile(config['checker_runner'], checker, config['checker_runner_flags'])
        defines.append('-DRBX_CMS_CHECKER="%s"' % checker)
    manager = os.path.join(build, 'manager')
    _compile(config['manager'], manager, config['manager_flags'], *defines)
    dataset = {
        'task_type': config['task_type'],
        'task_type_parameters': config['task_type_parameters'],
        'managers': {
            'manager': Manager(
                'manager',
                cacher.put_file_from_path(manager, 'Manager for task %s' % _TASK),
            )
        },
    }
    return dataset


def _checker(config):
    # Built against rbx's testlib patched for CMS (`-DRBX_CMS`), in a copy of
    # `files/` so `#include "testlib.h"` finds that variant first.
    from cms.db import Manager
    from cms.db.filecacher import FileCacher

    build = tempfile.mkdtemp()
    for name in os.listdir(_FILES):
        if os.path.isfile(os.path.join(_FILES, name)):
            shutil.copy(os.path.join(_FILES, name), os.path.join(build, name))
    shutil.copy(
        os.path.join(_FILES, config['testlib']), os.path.join(build, 'testlib.h')
    )
    checker = os.path.join(build, 'checker')
    subprocess.run(
        ['g++', '-x', 'c++']
        + list(config['flags'])
        + ['-static', '-DRBX_CMS']
        + ['-I', build, '-o', checker, os.path.join(build, config['source'])],
        check=True,
    )
    digest = FileCacher().put_file_from_path(checker, 'Checker for task %s' % _TASK)
    return {'checker': Manager('checker', digest)}


general = dict(CONFIG['general'])
for _key in CONFIG['durations']:
    general[_key] = datetime.timedelta(seconds=general[_key])
datasets = {
    'tests': {
        'score_type': CONFIG['score_type'],
        'score_type_parameters': CONFIG['score_type_parameters'],
    }
}
if CONFIG.get('checker'):
    datasets['tests']['managers'] = _checker(CONFIG['checker'])
_pack = False
if CONFIG.get('communication'):
    datasets['tests'].update(_communication(CONFIG['communication']))
    _pack = bool(CONFIG['communication']['checker_runner'])


def _grader(config):
    # The grader (or, in a Communication task, the stub) and the headers it and
    # the submissions include, stored as managers: CMS compiles each submission
    # together with them.
    from cms.db import Manager
    from cms.db.filecacher import FileCacher

    cacher = FileCacher()
    return {
        stored: Manager(
            stored,
            cacher.put_file_from_path(
                os.path.join(_FILES, source), '%s for task %s' % (stored, _TASK)
            ),
        )
        for stored, source in config['managers'].items()
    }


if CONFIG.get('grader'):
    datasets['tests'].setdefault('managers', {}).update(_grader(CONFIG['grader']))
    if 'task_type' in CONFIG['grader']:
        datasets['tests']['task_type'] = CONFIG['grader']['task_type']
        datasets['tests']['task_type_parameters'] = CONFIG['grader'][
            'task_type_parameters'
        ]


def _attachments(attachments):
    from cms.db import Attachment
    from cms.db.filecacher import FileCacher

    cacher = FileCacher()
    return {
        name: Attachment(
            name,
            cacher.put_file_from_path(
                os.path.join(_FILES, source), 'Attachment for task %s' % _TASK
            ),
        )
        for name, source in attachments.items()
    }


if CONFIG.get('attachments'):
    general['attachments'] = _attachments(CONFIG['attachments'])
if _pack or CONFIG['public'] != 'all':
    datasets['tests']['testcases'] = _testcases(_pack)
